import json, os, re, subprocess
import claude_sessions as cs

def blob(repo, commit, path):
    try:
        return subprocess.run(["git", "-C", repo, "show", f"{commit}:{path}"], capture_output=True, text=True, check=True).stdout
    except Exception:
        return None

def checkpoint(repo, n):
    out = subprocess.run(["git", "-C", repo, "log", "--format=%h", f"--grep=^bench: after S{n}$"], capture_output=True, text=True).stdout.split()
    return out[0] if out else None

def simulate(cmd, repo, commit):
    m = re.match(r"^\s*(cat|tail|head)\s+(-n\s*|-)?(\d+)?\s*(.*)$", cmd.strip())
    if not m:
        return None
    prog, _, k, rest = m.groups()
    paths = rest.split()
    txt = ""
    for p in paths:
        b = blob(repo, commit, p)
        if b is None:
            return None
        lines = b.splitlines(True)
        if prog == "tail" and k:
            lines = lines[-int(k):]
        if prog == "head" and k:
            lines = lines[: int(k)]
        txt += "".join(lines)
    return len(txt)

def main():
    for rep in (1, 2, 3):
        cd = f"{cs.ROOT}/round-4-sofar-r{rep}/sofar/r{rep}"
        for n in cs.CLAUDE_S:
            for sid in cs.session_ids(f"{cd}/artifacts/S{n}/agent.stdout"):
                for p in cs.paths_for(sid, 4, "sofar", rep):
                    rw, uses, res = {}, {}, {}
                    cwd = None
                    for line in open(p):
                        e = json.loads(line)
                        cwd = cwd or e.get("cwd")
                        if e.get("type") == "attachment":
                            a = e["attachment"]
                            if a.get("hookEvent") == "PreToolUse" and "updatedInput" in (a.get("stdout") or ""):
                                rw[a["toolUseID"]] = json.loads(a["stdout"])["hookSpecificOutput"]["updatedInput"]["command"]
                            continue
                        m = e.get("message") or {}
                        if isinstance(m.get("content"), list):
                            for c in m["content"]:
                                if c.get("type") == "tool_use":
                                    uses[c["id"]] = c["input"].get("command", "")
                                if c.get("type") == "tool_result":
                                    res[c["tool_use_id"]] = cs.clen(c.get("content"))
                    for tid, new in rw.items():
                        repo = cwd or f"{cd}/repo"
                        prev = checkpoint(f"{cd}/repo", n - 1) if n not in (15, 16, 17) else checkpoint(f"{cd}/repo", 14)
                        orig = simulate(uses.get(tid, ""), f"{cd}/repo", prev) if prev else None
                        print(f"r{rep} S{n}: {uses.get(tid,'')[:70]!r} -> got {res.get(tid)} chars; original would be ~{orig}")

if __name__ == "__main__":
    main()
